package week_01;
import javax.swing.*;import java.awt.*;
public class CipherFrame extends JFrame {
 private final String algorithm; private final JTextArea plain=new JTextArea(4,48),cipher=new JTextArea(4,48);private final JTextField key=new JTextField(18);private final JLabel status=new JLabel("Sẵn sàng.");
 public CipherFrame(String a){super(a+" Cipher");algorithm=a;setDefaultCloseOperation(DISPOSE_ON_CLOSE);setSize(720,480);setLocationRelativeTo(null);setLayout(new BorderLayout(12,12));JPanel p=new JPanel(new GridBagLayout());p.setBorder(BorderFactory.createEmptyBorder(18,24,10,24));GridBagConstraints g=new GridBagConstraints();g.insets=new Insets(5,5,5,5);g.fill=GridBagConstraints.HORIZONTAL;g.gridx=0;g.gridy=0;g.gridwidth=2;JLabel title=new JLabel("MẬT MÃ "+a.toUpperCase());title.setFont(new Font("Segoe UI",Font.BOLD,20));p.add(title,g);g.gridwidth=1;g.gridy++;g.gridx=0;p.add(new JLabel("Plaintext:"),g);g.gridx=1;p.add(new JScrollPane(plain),g);g.gridy++;g.gridx=0;p.add(new JLabel("Key:"),g);g.gridx=1;key.setText(CipherTongHop.sampleKey(a));p.add(key,g);g.gridy++;g.gridx=0;p.add(new JLabel("Ciphertext:"),g);g.gridx=1;p.add(new JScrollPane(cipher),g);JPanel buttons=new JPanel(new FlowLayout(FlowLayout.LEFT));JButton en=new JButton("Encrypt"),de=new JButton("Decrypt"),op=new JButton("Open File"),sv=new JButton("Save File");for(JButton b:new JButton[]{en,de,op,sv})buttons.add(b);g.gridy++;g.gridx=0;g.gridwidth=2;p.add(buttons,g);en.addActionListener(e->apply(true));de.addActionListener(e->apply(false));op.addActionListener(e->file(false));sv.addActionListener(e->file(true));add(p,BorderLayout.CENTER);status.setBorder(BorderFactory.createEmptyBorder(4,24,12,24));add(status,BorderLayout.SOUTH);}
 private void apply(boolean enc){try{String input=enc?plain.getText():cipher.getText();if(input.isEmpty())throw new IllegalArgumentException("Hãy nhập dữ liệu trước khi thực hiện.");String out=enc?CipherTongHop.encrypt(algorithm,input,key.getText()):CipherTongHop.decrypt(algorithm,input,key.getText());if(enc)cipher.setText(out);else plain.setText(out);status.setText((enc?"Đã mã hóa ":"Đã giải mã ")+algorithm+".");}catch(Exception ex){JOptionPane.showMessageDialog(this,ex.getMessage(),"Dữ liệu không hợp lệ",JOptionPane.ERROR_MESSAGE);}}
 private void file(boolean save){String path=save?FileTextIO.save(this,cipher,algorithm.toLowerCase()+"_ciphertext.txt"):FileTextIO.open(this,cipher);if(path!=null)status.setText((save?"Đã lưu ":"Đã mở ")+path);}
}
